# ---- output ----
def dur(t):
    p = t.count("(pause)"); w = len(re.sub(r"\(pause\)", "", t).split())
    return max(1.8, w / 2.45) + 1.2 * p
rows, t0 = [], 0.0
for i, (text, see, meth, refs, st) in enumerate(F, 1):
    meth = re.sub(r"#([a-z0-9-]+)", lambda m: "#" + str(KEYS.get(m.group(1), "??" + m.group(1))), meth)
    d = dur(text); rows.append((i, t0, text, see, meth, refs, st)); t0 += d
kinds = {}
for r in rows:
    k = r[4].split("←")[0].split(" ")[0]; k = "NEW" if k.startswith("NEW") else k; kinds[k] = kinds.get(k, 0) + 1
mm = lambda s: f"{int(s//60)}:{s%60:04.1f}"
HEADS = {"In the middle of the night": "۰ · The River Screams", "You leave in the morning": "۱ · No Walls", "At midday, half a fish": "۲ · The Ones Who Didn't Make It",
         "Sixty-six million years later, it's the same night": "۳ · Meanwhile", "In the morning, your legs": "۴ · Black Ice", "On the fourth day": "۵ · The Shell",
         "Sixty-six million years later, a car stops": "۶ · The Roots", "By the sixth day": "۷ · The Same Day", "At noon you sit down": "۸ · Back",
         "In the morning, the light is different": "۹ · The Sea Is Slow"}
out = ["# شات‌لیست STILLCUT · فصل ۱ قسمت ۴ (script-en-FINAL)", "",
       f"**{len(rows)} قاب · حدود {mm(t0)}** · " + " · ".join(f"{k} {v}" for k, v in sorted(kinds.items(), key=lambda x: -x[1])), "",
       "> ستون **وضعیت**: A=دست‌ها (wrapped = نوار تیره‌ی ضربدری + پرز، شیت Q1، کل قسمت) · K=کوله · FS=لاک آتیش (درِ گِلی) · WS=لاک آب · P=پیپ · M=جفتش (خاکستری، خال سفید روی سینه) · H=پا (پوتین / پای برهنه / پاشنه‌ی پیچیده از روز ۹۴) · L=نور.",
       "> مکان‌ها: `a4:L1` جاده‌ی شرق · `a4:L2` تنگه · `a4:L3` گله · `a4:L4` رود پهن · `a4:U1/U2` لونه · `a4:U6` دریا · `a4:U7` صخره‌ی بدلندز. **هیچ قابی تونل، در سنگی یا درخت بزرگِ خونه‌ی قبلی رو نداره** (به‌جز فلش‌بک‌های OLD).", ""]
for i, a, text, see, meth, refs, st in rows:
    for h, name in HEADS.items():
        if text.startswith(h): out += ["", "### " + name]
    tag = "🆕 " if meth.startswith("NEW") else ""
    out.append(f"- **#{i}** · {mm(a)} · `{meth}` {tag}— {see}" + (f" · _رفرنس: {refs}_" if refs else "") + (f" · **وضعیت:** `{st}`" if st else ""))
    out.append(f"  > {text}")
open(os.path.join(H, "shotlist.md"), "w").write("\n".join(out) + "\n")
print(len(rows), "frames,", mm(t0), kinds)
print("unresolved:", [r[0] for r in rows if "??" in r[4]])
